function ForbiddenDataManager:IsCanMatch(carid)
    local cardata = CarDataManager:Get():GetCarDataByCarID(carid)
    if cardata == nil then
        CommonTipsHelper:Get():ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.NoSelectCar))
        return false
    end
    local isCanMatch = true
    ---@type grooveid_config_cell[]
    local cfg = ClientDataManager:Get():GetDataTable(ConfigNames.grooveid_config).Get_BaseGrooveCfg()
    local partNameList = {}
    for k, v in pairs(PartGrooveID) do
        if cardata.assembleMgr:GetNodeByGrooveID(v) and cardata.assembleMgr:GetNodeByGrooveID(v):GetBagId() ~= 0 then
            local id = cardata.assembleMgr:GetNodeByGrooveID(v):GetBagId()
            local cell = KnapsackDataManager:Get():GetArticleByCellID(id)
            print("      cell GetPartBaseCfg  "..cell:GetPartBaseCfg().C_ID.."  GetPartConfig  "..cell:GetPartConfig().C_ID)
            if self.forbiddenBaseIDDict[cell:GetPartBaseCfg().C_ID] then
                table.insert(partNameList, CommonHelper:GetTempStr_Default(cell:GetPartConfig().partname))
                isCanMatch = true
            end
        end
    end
    if not isCanMatch then
        local title = CommonHelper:GetTempStr_Default(TemplateStringID.ForbiddenTipTile)
        local content = CommonHelper:GetTempStr_Default(TemplateStringID.ForbiddenTipContent) .. table.concat(partNameList, "、") .. '。'
        MessageBoxHelp:Get():OpenBox_OK(UIColor.Blue, content, title, nil, nil, true, false, true)
    end
    return isCanMatch
end

function ForbiddenDataManager:SetData()
    local seasonid = RaceTrotManager:Get():GetSeasonId()
    ---@type dictfastseason_config_cell
    local fastseasontab = CommonHelper:GetTableDataByID(ConfigNames.dictfastseason_config, seasonid)
    self.isUnForbidden = (fastseasontab.unusesubtype == nil or fastseasontab.unusesubtype == "0") and (fastseasontab.unusesubtype == nil or fastseasontab.unusebasepartid == "0")
    ---@type dictpartbase_config
    local partbasetab = ClientDataManager:Get():GetDataTable(ConfigNames.dictpartbase_config)
    if fastseasontab.unusesubtype ~= nil and fastseasontab.unusesubtype ~= "0" then
        local list = stringSplit(fastseasontab.unusesubtype, ';')
        for i = 1, #list do
            local sublist = stringSplitToNumber(list[i], ':')
            ---@type dictpartbase_config_cell
            local partbasedatatable = partbasetab.GetDataByType(sublist[1], sublist[2])
            if self.forbiddenDict[sublist[1]] == nil then
                self.forbiddenDict[sublist[1]] = {}
            end
            if self.forbiddenDict[sublist[1]][sublist[2]] == nil then
                self.forbiddenDict[sublist[1]][sublist[2]] = {}
            end
            for j = 1, #partbasedatatable do
                local forbiddenData = ForbiddenData()
                forbiddenData:SetData(partbasedatatable[j])
                if forbiddenData.partCfg == nil then
                    logError("  partCfg==nil  ID:" .. forbiddenData.baseCfg.C_ID)
                else
                    self.forbiddenBaseIDDict[forbiddenData.baseCfg.C_ID] = true
                    table.insert(self.forbiddenDict[sublist[1]][sublist[2]], forbiddenData)
                end
            end
        end
    end
    if fastseasontab.unusebasepartid ~= nil and fastseasontab.unusebasepartid ~= "0" then
        local list = stringSplitToNumber(fastseasontab.unusebasepartid, ':')
        ---@type dictpartbase_config_cell
        for i = 1, #list do
            local partbasedata = partbasetab.GetById(list[i])
            if self.forbiddenDict[partbasedata.parttype] == nil then
                self.forbiddenDict[partbasedata.parttype] = {}
            end
            if self.forbiddenDict[partbasedata.parttype][partbasedata.subtype] == nil then
                self.forbiddenDict[partbasedata.parttype][partbasedata.subtype] = {}
            end
            local forbiddenData = ForbiddenData()
            forbiddenData:SetData(partbasedata)
            self.forbiddenBaseIDDict[forbiddenData.baseCfg.C_ID] = true
            table.insert(self.forbiddenDict[partbasedata.parttype][partbasedata.subtype], forbiddenData)
        end
    end
end

function ForbiddenDataManager:Clear()
    self.forbiddenDict = {}
    self.forbiddenBaseIDDict = {}
end